def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Increasing part: maximum sum of increasing subsequence ending at i
    inc = arr[:]
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # Decreasing part: maximum sum of decreasing subsequence starting at i
    dec = arr[:]
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # Combine both parts, subtract arr[i] once because it's counted twice
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - arr[i])

    return max_bitonic
